INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8501, '1 Kings 8:66', '1 Kings', 8, 66, '&nbsp;په اتمه ورځ سليمان خلق رُخصت کړل. هغوئ ټولو د هغۀ صِفت کولو او د هغه ټولو برکتونو په وجه خوشحاله کورونو ته لاړل چې کوم برکتونه مالِک خُدائ خپل خِدمت کوونکى داؤد او د هغۀ خلقو بنى اِسرائيلو له ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8502, '1 Kings 9:1', '1 Kings', 9, 1, '&nbsp;کله چې سليمان بادشاه د مالِک خُدائ کور، خپل محل او د هغه هر څۀ جوړول ختم کړل چې څۀ يې جوړول غوښتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8503, '1 Kings 9:2', '1 Kings', 9, 2, '&nbsp;نو مالِک خُدائ په دوېم ځل هغۀ ته راڅرګند شو، لکه څنګه چې هغه په جبعون کښې څرګند شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8504, '1 Kings 9:3', '1 Kings', 9, 3, '&nbsp;مالِک خُدائ هغۀ ته وفرمائيل، ”ما ستا دُعا اورېدلې ده، کومه چې تا زما په وړاندې کړې ده. کوم کور چې تا جوړ کړے دے هغه زۀ مقدس کوم او هغه به داسې ځائ وى چې همېشه به هلته زما عبادت کيږى. زما به په دې نظر وى او همېشه به زړۀ کښې اوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8505, '1 Kings 9:4', '1 Kings', 9, 4, '&nbsp;او کۀ تا په صداقت او د زړۀ د اخلاصه زما خِدمت کولو لکه چې ستا پلار داؤد کولو او تا زما قانون او هغه هر څۀ منل چې ما يې حُکم درکړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8506, '1 Kings 9:5', '1 Kings', 9, 5, '&nbsp;نو زۀ به خپله هغه وعده پوره کړم چې ما ستا پلار داؤد سره کړې وه چې ما هغۀ ته وفرمائيل چې ستا د اولاد نه به همېشه يو کس د بنى اِسرائيل په تخت ناست وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8507, '1 Kings 9:6', '1 Kings', 9, 6, '&nbsp;خو کۀ تا يا ستا اولاد زما تابعدارى پرېښوده، چې ما کوم قانون او حُکمونه درکړى دى، د هغې نافرمانى مو وکړه او د نورو خُدايانو عبادت مو وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8508, '1 Kings 9:7', '1 Kings', 9, 7, '&nbsp;نو زۀ به خپل خلق بنى اِسرائيليان د هغه مُلک نه لرې کړم کوم چې ما ورکړے دے. او زۀ به دا کور هم پرېږدم چې ما د خپل عبادت دپاره مقدس کړے دے. ټول قومونه به د بنى اِسرائيلو په مُلک پورې خندا کوى او سپک به ورته ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8509, '1 Kings 9:8', '1 Kings', 9, 8, '&nbsp;دا کور به د کنډر يو ډېرے شى او چې هر څوک هم ورباندې تېريږى نو وبه لړزيږى او حېران به شى. هغوئ به تپوس کوى چې مالِک خُدائ په دې مُلک او کور باندې داسې ولې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8510, '1 Kings 9:9', '1 Kings', 9, 9, '&nbsp;نو خلق به وائى چې هغوئ مالِک خُدائ پرېښے وو، چا چې د هغوئ پلار نيکۀ د مِصر نه راوويستل. هغوئ نور خُدايان راټينګ کړل او د هغوئ عبادت او خِدمت يې وکړو. نو دا ځکه مالِک خُدائ ورباندې دا تباهى راوستې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8511, '1 Kings 9:10', '1 Kings', 9, 10, '&nbsp;د سليمان د مالِک خُدائ په کور او خپل محل باندې شل کاله ولګېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8512, '1 Kings 9:11', '1 Kings', 9, 11, '&nbsp;د صور بادشاه حيرام هغۀ له دِيار او د نختر لرګو او د هغه ټولو سرو زرو بندوبست وکړو چې هغۀ د دې کار دپاره غوښتى وُو. کله چې دا کار ختم شو، نو سليمان بادشاه حيرام له د ګليل په علاقه کښې شل ښارونه ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8513, '1 Kings 9:12', '1 Kings', 9, 12, '&nbsp;حيرام بادشاه د هغه ښارونو ليدو له لاړو کوم چې سليمان ورکړى وُو، خو د هغۀ خوښ نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8514, '1 Kings 9:13', '1 Kings', 9, 13, '&nbsp;نو هغۀ سليمان ته ووئيل، ”زما وروره، دا څۀ رنګه ښارونه دى چې تا ما له راکړى دى؟“ نو په دې وجه تر اوسه پورې د هغه ځائ نوم کابول دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8515, '1 Kings 9:14', '1 Kings', 9, 14, '&nbsp;حيرام سليمان له د څلورو زرو کلو نه زيات سرۀ زر لېږلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8516, '1 Kings 9:15', '1 Kings', 9, 15, '&nbsp;سليمان بادشاه په مزدورانو باندې د مالِک خُدائ کور، محل، په غرۀ باندې پټى او د يروشلم دېوال جوړ کړو. په هغوئ يې د حصور، مِجدو او جزر ښارونه هم بيا جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8517, '1 Kings 9:16', '1 Kings', 9, 16, '&nbsp;د مِصر بادشاه فِرعون په جزر حمله کړې وه او دا يې قبضه کړے وو، د هغې اوسېدونکى يې ووژل او په ښار يې اور بل کړو. بيا هغۀ دا خپلې لور له د وادۀ په جهېز کښې په هغه وخت ورکړو چې سليمان ودوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8518, '1 Kings 9:17', '1 Kings', 9, 17, '&nbsp;سليمان د جزر ښار او لاندينے بيت‌حورون هم بيا جوړ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8519, '1 Kings 9:18', '1 Kings', 9, 18, '&nbsp;ورسره بعلات، د يهوداه په صحرا کښې تامار،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8520, '1 Kings 9:19', '1 Kings', 9, 19, '&nbsp;د ګودامونه والا ښارونه، د هغۀ د آسونو او جنګى ګاډو دپاره ښارونه او چې په يروشلم، لبنان او خپله ټوله بادشاهۍ کښې يې څۀ هم جوړول غوښتل نو هغه يې جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8521, '1 Kings 9:22', '1 Kings', 9, 22, '&nbsp;سليمان د بنى اِسرائيلو نه غلامان جوړ نۀ کړل، هغوئ د فوجيانو، مشرانو، فوجى آفسرانو، د ګاډو مشرانو او د آسونو والا په توګه خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8522, '1 Kings 9:23', '1 Kings', 9, 23, '&nbsp;په هغه مزدورانو باندې پينځۀ سوه او پنځوس آفسران مقرر کړے شوى وُو چې کومو مزدورانو د سليمان په منصوبو باندې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8523, '1 Kings 9:24', '1 Kings', 9, 24, '&nbsp;سليمان په غرۀ باندې پټى د هغې نه پس جوړ کړل چې د هغۀ ښځه د مِصر د بادشاه فِرعون لور، د داؤد د ښار نه هغه محل ته تلې وه چې د هغې دپاره يې جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8524, '1 Kings 9:25', '1 Kings', 9, 25, '&nbsp;سليمان به په کال کښې درې ځل سوزېدونکې نذرانې او د سلامتۍ نذرانې په هغه قربان‌ګاه پېش کولې چې کومه يې مالِک خُدائ ته جوړه کړې وه. هغۀ مالِک خُدائ ته خوشبوئى هم سوزوله. او داسې هغۀ د مالِک خُدائ کور جوړول پوره کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8525, '1 Kings 9:26', '1 Kings', 9, 26, '&nbsp;سليمان بادشاه په عصيون‌جابر کښې ډېر سمندرى جهازُونه هم جوړ کړل، عصيون‌جابر د ادوم په علاقه کښې د بحرِقُلزم په غاړه دے او ايلات ته نزدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8526, '1 Kings 9:27', '1 Kings', 9, 27, '&nbsp;حيرام بادشاه يو څو تکړه جهاز چلوونکى ورولېږل چې د سليمان د سړو مدد وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8527, '1 Kings 9:28', '1 Kings', 9, 28, '&nbsp;هغوئ د اوفير مُلک ته سفر وکړو او د هغه ځائ نه يې څوارلسو زرو کلو نه زيات سرۀ زر سليمان له راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8528, '1 Kings 10:1', '1 Kings', 10, 1, '&nbsp;د شيبا مَلِکه د سليمان د شُهرت نه خبر شوه، نو راغله چې په مشکلو سوالونو سره هغه معلوم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8529, '1 Kings 10:2', '1 Kings', 10, 2, '&nbsp;هغه يروشلم ته د يوې لوئې قبيلې سره راغله او د اوښانو يوه لويه قافله ورسره وه چې په مصالحو، قيمتى کاڼو او ډېر سرۀ زر ورباندې بار وُو. کله چې هغه او سليمان مِلاو شول، نو هغې ورسره هغه ټولې خبرې اترې وکړې چې د هغې په ذهن کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8530, '1 Kings 10:3', '1 Kings', 10, 3, '&nbsp;نو سليمان د ټولو سوالونو جواب ورکړو، داسې يو سوال هم نۀ وو چې هغۀ يې جواب نۀ شو ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8531, '1 Kings 10:4', '1 Kings', 10, 4, '&nbsp;د شيبا مَلِکه د سليمان په حِکمت پوهه شوه او هغه محل يې وليدو چې هغۀ جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8532, '1 Kings 10:5', '1 Kings', 10, 5, '&nbsp;هغې هغه خوراک وليدو چې د هغۀ په دسترخوان باندې پروت وو، د هغۀ د آفسرانو کوټې، د هغۀ د محل د نوکرانو اِنتظام او هغه لِباس چې هغوئ اغوستے وو، د هغۀ ساقيان يې وليدل او هغه پوره سوزېدونکې نذرانې يې هم وليدې چې هغۀ به د مالِک خُدائ په کور کښې پېش کولې. نو په دې هر څۀ باندې حقه حېرانه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8533, '1 Kings 10:6', '1 Kings', 10, 6, '&nbsp;هغې سليمان بادشاه ته ووئيل، ”ما په خپل مُلک کښې چې ستا د کارنامو او حِکمت په حقله څۀ اورېدلى وُو نو هغه رښتيا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8534, '1 Kings 10:7', '1 Kings', 10, 7, '&nbsp;خو ما تر هغې پورې يقين نۀ کولو چې ترڅو زۀ په خپله راغلې نۀ وم او هر څۀ مې کتلى نۀ وُو. خو زۀ د دې په نيمه هم نۀ وم خبر، ما ته چې څۀ وئيلى شوى وُو نو ستا حِکمت او دولت د هغې نه ډېر زيات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8535, '1 Kings 10:8', '1 Kings', 10, 8, '&nbsp;ستا ښځې څومره خوش قسمته دى او ستا نوکران څومره خوش قسمته دى، هغوئ هر وخت ستا په وړاندې وى او ستا د حِکمت خبرې اورېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8536, '1 Kings 10:9', '1 Kings', 10, 9, '&nbsp;د مالِک خُدائ ستا د خُدائ پاک ثناء صِفت دې وى، چې هغۀ دا ښودلى دى چې هغه ستا نه څومره خوشحاله دے چې تۀ يې د بنى اِسرائيلو بادشاه جوړ کړے يې. ځکه چې د بنى اِسرائيلو سره د هغۀ مينه د تل دپاره ده، نو هغۀ تۀ د هغوئ بادشاه جوړ کړے يې چې د اِنصاف او صداقت نه کار واخلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8537, '1 Kings 10:10', '1 Kings', 10, 10, '&nbsp;د شيبا مَلِکه سليمان بادشاه ته هغه تُحفې پېش کړې کومې چې هغې راوړې وې، د څلور زره کېلو نه زيات سرۀ زر او په ډېر زيات مِقدار کښې مصالحې او قيمتى کاڼى هم. هغې چې کومې مصالحې ورکړې هغه دومره زياتې وې چې هيچا هم دومره بيا ورنۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8538, '1 Kings 10:11', '1 Kings', 10, 11, '&nbsp;د حيرام سمندرى جهازونو چې کومې د اوفير نه سرۀ زر راوړى وُو، د هغه ځائ نه يې په ډېر زيات مِقدار کښې د صُندل لرګى او قيمتى کاڼى هم راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8539, '1 Kings 10:12', '1 Kings', 10, 12, '&nbsp;سليمان دا لرګى د مالِک خُدائ کور او محل په ستنو کښې استعمال کړل او د دې نه يې د سندرغاړو دپاره بينجو او ربابُونه هم جوړ کړل. دا د ټولو نه ښۀ د صُندل لرګى وُو چې د بنى اِسرائيلو مُلک ته راوړے شوى وُو، د دې په شان لرګے بيا نۀ دے ليدلے شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8540, '1 Kings 10:13', '1 Kings', 10, 13, '&nbsp;سليمان بادشاه د شيبا مَلِکه له هغه هر څۀ ورکړل چې څۀ يې غوښتل، دا د هغه نورو شاهى تُحفو نه علاوه وُو چې هغې له يې د سخاوت سره ورکړې وې. بيا هغه او د هغې ډله د شيبا مُلک ته راواپس شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8541, '1 Kings 10:14', '1 Kings', 10, 14, '&nbsp;سليمان بادشاه ته هر کال تقريباً درويشت زره کلو سرۀ زر مِلاوېدل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8542, '1 Kings 10:15', '1 Kings', 10, 15, '&nbsp;د دې نه علاوه چې سوداګرو کوم محصُول ورکولو، د تجارت ګټه او چې د بنى اِسرائيلو د مُلک د ضِلعو حاکِمانو او د عربو بادشاهانو چې کوم محصُول ورکولو هغه هم ورته مِلاوېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8543, '1 Kings 10:16', '1 Kings', 10, 16, '&nbsp;سليمان دوه سوه لوئ ډالونه جوړ کړل، چې په هر يو باندې تقريباً اووۀ کلو د ټکولے شوو سرو زرو پترى خېژولے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8544, '1 Kings 10:17', '1 Kings', 10, 17, '&nbsp;هغۀ درې سوه واړۀ ډالونه هم جوړ کړل، چې په هر يو باندې تقريباً دوه کلو د ټکولے شوو سرو زرو پترى خېژولے شوى وُو. هغۀ دا ټول ډالونه په هغه دربار کښې کېښودل چې نوم يې د لبنان ځنګل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8545, '1 Kings 10:18', '1 Kings', 10, 18, '&nbsp;هغۀ يو لوئ تخت هم جوړ کړو چې يوه حِصه يې د هاتى په غاښونو پټه وه او نور په سوچه سرو زرو باندې پټ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8546, '1 Kings 10:21', '1 Kings', 10, 21, '&nbsp;د سليمان د څښلو ټولې پيالۍ د سرو زرو نه جوړې وې او د لبنان د ځنګل په دربار کښې ټول لوښى د سوچه سرو زرو وُو. سپين زر په کښې بېخى نۀ وُو استعمال شوى، ځکه چې د سليمان په وخت کښې دا قيمتى نۀ شو ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8547, '1 Kings 10:22', '1 Kings', 10, 22, '&nbsp;هغۀ سمندرى جهازُونه لرل چې د حيرام د جهازونو سره چلېدل. هر درې کاله پس به دا راواپس کېدل، چې سرۀ زر، سپين زر، د هاتى غاښونه، شادوګان او طاؤسان به يې راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8548, '1 Kings 10:23', '1 Kings', 10, 23, '&nbsp;سليمان د دُنيا د نورو ټولو بادشاهانو نه زيات مالداره او د ټولو نه زيات د حِکمت خاوند وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8549, '1 Kings 10:24', '1 Kings', 10, 24, '&nbsp;او ټولې دُنيا به دا غوښتل چې هغۀ له راشى او د هغۀ حِکمت ته غوږ ونيسى چې خُدائ پاک هغۀ له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8550, '1 Kings 10:25', '1 Kings', 10, 25, '&nbsp;چې هر څوک به هغۀ له راتلو نو هغۀ له به يې څۀ تُحفه راوړه، لکه سپين زر او سرۀ زر، چُوغې، وسلې، مصالحې، آسونه، او قچر. کال په کال به داسې کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8551, '1 Kings 10:26', '1 Kings', 10, 26, '&nbsp;سليمان د څوارلسو سوو جنګى ګاډو او دولسو زرو په آسونو سوارو فوجيانو يو لوئ لښکر جوړ کړو. هغۀ څۀ په يروشلم کښې وساتل او باقى نور يې په مختلفو ښارونو کښې دېره کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8552, '1 Kings 10:27', '1 Kings', 10, 27, '&nbsp;د هغۀ په بادشاهۍ کښې سپين زر په يروشلم کښې د کاڼو په شان عام وُو او دِيار د يهوداه غرونو په لمن کښې د چِنار په شان ډېر تېر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8553, '1 Kings 10:28', '1 Kings', 10, 28, '&nbsp;د سليمان سوداګرو د مِصر او قوعى نه آسونه اخستل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8554, '1 Kings 10:29', '1 Kings', 10, 29, '&nbsp;هغوئ به يوه جنګى ګاډۍ د مِصر نه په شپږ سوه د سپينو زرو په سيکو او آس به يې په يو نيم سل د سپينو زرو په سيکو اخستلو او حِتى او شامى بادشاهانو له به يې د خرڅولو دپاره آسونه او جنګى ګاډۍ لېږلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8555, '1 Kings 11:1', '1 Kings', 11, 1, '&nbsp;او سليمان د پردى مُلک د ډېرو ښځو سره مينه کوله. د فِرعون د لور نه علاوه هغۀ حِتۍ، موآبۍ، عمونۍ، ادومۍ او صيدانۍ ښځې وادۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8556, '1 Kings 11:2', '1 Kings', 11, 2, '&nbsp;مالِک خُدائ بنى اِسرائيلو له دا حُکم ورکړے وو چې د دې قومونو سره ودونه مۀ کوئ ځکه چې د دې په وجه به د بنى اِسرائيلو زړونه نورو خُدايانو ته واوړى، خو سليمان د غېرو قومو ښځو مينه نۀ پرېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8557, '1 Kings 11:3', '1 Kings', 11, 3, '&nbsp;سليمان اووۀ سوه شهزادګۍ وادۀ کړې او درې سوه وينځې يې هم وې. نو هغوئ د هغۀ زړۀ د خُدائ پاک نه واړولو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8558, '1 Kings 11:4', '1 Kings', 11, 4, '&nbsp;او چې سليمان بوډا شو نو هغوئ د هغۀ زړۀ پردو خُدايانو ته واړولو او هغه د خپل پلار داؤد په شان د مالِک خُدائ د خپل خُدائ پاک پوره وفادار پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8559, '1 Kings 11:5', '1 Kings', 11, 5, '&nbsp;هغۀ د صيدان عستارات مجسمې او د عمون د پليت مولک بُت عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8560, '1 Kings 11:6', '1 Kings', 11, 6, '&nbsp;نو سليمان هغه څۀ وکړل چې څۀ د مالِک خُدائ په نظر کښې بد وُو او هغۀ د مالِک خُدائ پوره تابعدارى نۀ کوله، لکه څنګه چې د هغۀ پلار داؤد کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8561, '1 Kings 11:7', '1 Kings', 11, 7, '&nbsp;هغۀ د يروشلم نمرخاتۀ طرف ته په غرۀ باندې د موآب د پليت معبود کموس او د عمون د پليت مولک بُت د عبادت دپاره يوه عبادتخانه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8562, '1 Kings 11:8', '1 Kings', 11, 8, '&nbsp;هغۀ د عبادت ځايونه هم جوړ کړل چرته به چې د هغۀ د پردى مُلک ټولو ښځو خوشبوئى سوزوله او خپلو خُدايانو ته به يې نذرانې پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8563, '1 Kings 11:11', '1 Kings', 11, 11, '&nbsp;او ورته يې وفرمائيل، ”تا قصداً ما سره خپل لوظ مات کړے دے او زما د حُکمونو نافرمانى دې کړې ده، نو زۀ به خامخا ستا نه بادشاهى اخلم او ستا يو نوکر له به يې ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8564, '1 Kings 11:12', '1 Kings', 11, 12, '&nbsp;خو ستا د پلار داؤد په خاطر زۀ به داسې ستا په ژوند کښې نۀ کوم، خو ستا د زوئ په بادشاهۍ کښې به يې وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8565, '1 Kings 11:13', '1 Kings', 11, 13, '&nbsp;خو زۀ به د هغۀ نه ټوله بادشاهى نۀ اخلم، زۀ به د خپل خِدمت کوونکى داؤد او د خپل خوښ شوى ښار يروشلم د خاطره يوه قبيله هغۀ ته پرېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8566, '1 Kings 11:14', '1 Kings', 11, 14, '&nbsp;نو مالِک خُدائ د ادوم شاهى خاندان حدد راوچت کړو چې د سليمان خِلاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8567, '1 Kings 11:17', '1 Kings', 11, 17, '&nbsp;خو حدد او د هغۀ د پلار څۀ ادوميان نوکران مِصر ته تښتېدلى وُو. (په هغه وخت کښې حدد ماشوم وو.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8568, '1 Kings 11:18', '1 Kings', 11, 18, '&nbsp;هغوئ ميديان پرېښودو او فاران ته لاړل، چې هلته يو څو نور سړى ورسره ملګرى شول. بيا هغوئ مِصر ته سفر وکړو او فِرعون له لاړل، هغۀ حدد له لږه زمکه او کور ورکړو او د خوراک بندوبست يې ورله وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8569, '1 Kings 11:19', '1 Kings', 11, 19, '&nbsp;او د فِرعون حدد دومره خوښ شو چې هغۀ له يې د خپلې ښځې يعنې د مَلِکې تحفنحيس خور وکړه، چې حدد يې وادۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8570, '1 Kings 11:20', '1 Kings', 11, 20, '&nbsp;د هغې نه يې يو زوئ جنوبت پېدا شو، چې هغه مَلِکې د فِرعون په محل کښې ساتلو او هلته د فِرعون د زامنو سره اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8571, '1 Kings 11:21', '1 Kings', 11, 21, '&nbsp;کله چې په مِصر کښې حدد ته دا پېغام ورسېدو چې داؤد او د لښکر مشر يوآب مړۀ شوى دى، نو حدد فِرعون ته ووئيل، ”ما پرېږده چې زۀ واپس خپل مُلک ته لاړ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8572, '1 Kings 11:22', '1 Kings', 11, 22, '&nbsp;فِرعون ترې نه تپوس وکړو، ”دلته تا ته د څۀ کمے دے؟ چې واپس خپل کور ته تلل غواړې.“ حدد فِرعون له جواب ورکړو، ”نه، بس ما له د تلو اجازت راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8573, '1 Kings 11:23', '1 Kings', 11, 23, '&nbsp;خُدائ پاک د اليدع زوئ رِزون هم د سليمان خِلاف کړو. رِزون د خپل نېک يعنې د ضوباه بادشاه هدد‌عزر نه تښتېدلے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8574, '1 Kings 11:24', '1 Kings', 11, 24, '&nbsp;او هغه د بدمعاشانو د يوې قبيلې مشر شوے وو. دا د هغې نه پس شوى وُو چې کله داؤد هدد‌عزر له شکست ورکړو. رِزون او د هغۀ سړى لاړل او په دمشق کښې اوسېدل، چې هلته خپلو سړو هغه په دمشق کښې بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8575, '1 Kings 11:25', '1 Kings', 11, 25, '&nbsp;د سليمان په ټول ژوند کښې رِزون د بنى اِسرائيلو دشمن وو او د حدد په شان يې هغوئ په تکليف کول، هغۀ د بنى اِسرائيلو نه نفرت کولو خو په خپله يې په شام بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8576, '1 Kings 11:26', '1 Kings', 11, 26, '&nbsp;يو بل سړے د نباط زوئ يربعام د سليمان بادشاه خِلاف شو چې هغه د سليمان خپل يو آفسر وو. يربعام په اِفرائيم کښې د صريده وو. او د يربعام د کونډې مور نوم صروعه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8577, '1 Kings 11:27', '1 Kings', 11, 27, '&nbsp;دا د هغۀ د بغاوت قيصه ده. سليمان د يروشلم نمرخاتۀ طرف ته بره ختلى پټى جوړول او د ښار دېوالونه يې مرمت کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8578, '1 Kings 11:28', '1 Kings', 11, 28, '&nbsp;يربعام يو تکړه زلمے وو او کله چې سليمان ته پته ولګېده چې هغه څومره محنتى دے، نو هغه يې د منسى او اِفرائيم قبيلو په علاقه کښې د هغه مزدورانو مشر جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8579, '1 Kings 11:29', '1 Kings', 11, 29, '&nbsp;يوه ورځ کله چې يربعام د يروشلم نه سفر کولو نو په لاره باندې اخياه پېغمبر ورسره مِلاو شو، اخياه د سيلا وو. او په مېدان کښې د هغوئ نه بغېر نور هيڅ څوک هم نۀ وُو، اخياه نوې چُوغه اغوستې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8580, '1 Kings 11:30', '1 Kings', 11, 30, '&nbsp;اخياه چې کومه نوې چُوغه اغوستې وه هغه يې وويستله او دولس ټوټې يې کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8581, '1 Kings 11:31', '1 Kings', 11, 31, '&nbsp;او يربعام ته يې ووئيل، ”لس ټوټې د ځان دپاره واخله، ځکه مالِک خُدائ د بنى اِسرائيلو خُدائ پاک تا ته وائى چې زۀ د سليمان نه بادشاهى اخلم او تا له به لس قبيلې درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8582, '1 Kings 11:32', '1 Kings', 11, 32, '&nbsp;سليمان به يوه قبيله زما د خِدمت کوونکى داؤد او د يروشلم په خاطر وساتى، دا هغه ښار دے چې د بنى اِسرائيل په ټول مُلک کښې ما خوښ کړے دے چې زما شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8583, '1 Kings 11:33', '1 Kings', 11, 33, '&nbsp;زۀ داسې ځکه کوم چې سليمان زۀ رد کړے يم او د پردو خُدايانو عبادت يې کړے دے يعنې، د صيدان د مجسمې عستارات، د موآب بُت کموس او د عمون بُت مولک. سليمان زما نافرمانى کړې ده، هغۀ زۀ نۀ يم رضا کړے او لکه څنګه چې د هغۀ پلار داؤد زما په قانون او حُکمونو عمل کولو داسې هغۀ نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8584, '1 Kings 11:34', '1 Kings', 11, 34, '&nbsp;خو زۀ به د سليمان نه ټوله بادشاهى نۀ اخلم او چې ترڅو ژوندے وى نو هغه به بادشاه ساتم. زۀ به داسې زما خِدمت کوونکى د داؤد د خاطره کوم، کوم چې ما خوښ کړے وو او هغۀ زما قانون او حُکمونه منلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8585, '1 Kings 11:35', '1 Kings', 11, 35, '&nbsp;زۀ به د سليمان د زوئ نه بادشاهى واخلم او لس قبيلې به درته حواله کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8586, '1 Kings 11:36', '1 Kings', 11, 36, '&nbsp;خو زۀ به د سليمان زوئ ته يوه قبيله پرېږدم، نو چې زما د خِدمت کوونکى داؤد د اولاد نه همېشه زما يو کس وى چې په يروشلم کښې بادشاهى کوى، هغه ښار چې ما خوښ کړے دے چې چرته به زما عبادت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8587, '1 Kings 11:37', '1 Kings', 11, 37, '&nbsp;يربعامه، زۀ به تا د اِسرائيل بادشاه جوړ کړم او تۀ به په هغه ټوله علاقه بادشاهى کوې چې ستا زړۀ يې غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8588, '1 Kings 11:38', '1 Kings', 11, 38, '&nbsp;کۀ تۀ زما د حُکم پوره تابعدارى کوې، زما د قانون په مطابق ژوند تېروې او زما د حُکمونو او تعليماتو په مطابق هغه کار کوې چې زما په نظر کښې ښۀ وى، لکه څنګه چې زما خِدمت کوونکى داؤد کول، نو زۀ به همېشه ستا مل يم. زۀ به تا د بنى اِسرائيلو بادشاه جوړ کړم او ستا اولاد به ستا نه پس خامخا بادشاهى کوى، لکه څنګه چې ما د داؤد دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8589, '1 Kings 11:39', '1 Kings', 11, 39, '&nbsp;د سليمان د ګناه په وجه به زۀ د داؤد اولاد له سزا ورکوم، خو دا به د همېشه دپاره نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8590, '1 Kings 11:40', '1 Kings', 11, 40, '&nbsp;سليمان د يربعام د وژلو کوشش کولو، خو يربعام د مِصر بادشاه سيساق له وتښتېدو او د سليمان تر مرګه پورې هلته ايسار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8591, '1 Kings 11:41', '1 Kings', 11, 41, '&nbsp;د سليمان کارنامې، د هغۀ حِکمت او چې نور څۀ يې هم کړى وُو هغه ټول ”د سليمان شاه نامه“ نومې کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8592, '1 Kings 11:42', '1 Kings', 11, 42, '&nbsp;هغه څلوېښت کاله په ټولو بنى اِسرائيلو باندې په يروشلم کښې بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8593, '1 Kings 11:43', '1 Kings', 11, 43, '&nbsp;هغه مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ رحُبعام د هغۀ نه پس بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8594, '1 Kings 12:1', '1 Kings', 12, 1, '&nbsp;بيا رحُبعام شِکم ته لاړو، چرته چې ټول اِسرائيليان راغونډ شوى وُو چې دے بادشاه جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8595, '1 Kings 12:2', '1 Kings', 12, 2, '&nbsp;کله چې د نباط زوئ يربعام د دې نه خبر شو چې څوک د سليمان بادشاه نه مِصر ته تښتېدلے وو، هغه د مِصر نه راواپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8596, '1 Kings 12:3', '1 Kings', 12, 3, '&nbsp;د شمالى قبيلو خلقو يربعام راوغوښتو او بيا هغه ټول ورسره رحُبعام له لاړل او هغۀ ته يې ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8597, '1 Kings 12:4', '1 Kings', 12, 4, '&nbsp;”ستا پلار سليمان په مونږ باندې درانۀ بوجونه کېښودل. کۀ تۀ دا بوجونه سپک کړې، نو مونږ به ستا وفادار خلق يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8598, '1 Kings 12:5', '1 Kings', 12, 5, '&nbsp;هغۀ ورته ووئيل، ”درې ورځې پس راشئ نو زۀ به تاسو له جواب درکړم.“ نو هغوئ لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8599, '1 Kings 12:6', '1 Kings', 12, 6, '&nbsp;رحُبعام بادشاه د هغه سپين‌ږيرو مشرانو سره مشوره وکړه کوم چې د هغۀ د پلار سليمان مشوره ورکوونکى وُو. هغۀ ترې نه تپوس وکړو، ”تاسو ما له مشوره راکړئ چې دې خلقو له څۀ جواب ورکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8600, '1 Kings 12:7', '1 Kings', 12, 7, '&nbsp;هغوئ ورته ووئيل، ”کۀ تۀ نن د دې خلقو خِدمتګار جوړ شې او د هغوئ خِدمت وکړې او خوږې خبرې ورسره وکړې، نو هغوئ به تل ستا خِدمت کوونکى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');